    expect(result.ok && result.task.title).toBe('Buy milk');
  });

  it('#3 AC3: adds nothing for an invalid title and leaves the list unchanged', () => {
    const tasks: Task[] = [];
    expect(createTask(tasks, { title: '   ' }, NOW, ids('a'))).toEqual({
